    14	    private final LocalDate date;
    15	    private final ReservationRepository reservationRepository;
    16	    private final RoomRepository roomRepository;
    17	    private List<Reservation> reservations;
    18	
    19	    public OccupancyReport(LocalDate date, ReservationRepository reservationRepository,
    20	                          RoomRepository roomRepository) {
    21	        this.date = date;
    22	        this.reservationRepository = reservationRepository;
    23	        this.roomRepository = roomRepository;
    24	    }
    25	
    26	    @Override
    27	    protected String reportName() {
    28	        return "occupancy";
    29	    }
    30	
    31	    @Override
    32	    protected String period() {
    33	        return date.format(DATE_FORMATTER);
    34	    }
    35	
    36	    @Override
    37	    protected String headerLine() {
    38	        return "room,type,reservation,check_in,check_out";
    39	    }
    40	
    41	    @Override
    42	    protected List<String> dataLines() {
    43	        reservations = reservationRepository.findPaidByNight(date);
    44	        List<String> lines = new ArrayList<>();
    45	
    46	        for (Reservation r : reservations) {
    47	            lines.add(String.format("%s,%s,%d,%s,%s",
    48	                r.getRoomNumber(),
    49	                roomRepository.findByNumber(r.getRoomNumber()).get().getType().name(),
    50	                r.getId(),
    51	                r.getCheckIn().format(DATE_FORMATTER),
    52	                r.getCheckOut().format(DATE_FORMATTER)
