     1	package com.pousadamarealta.report;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import com.pousadamarealta.domain.Reservation;
     5	import com.pousadamarealta.repository.ReservationRepository;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.*;
    11	
    12	public class RatePlansReport extends CsvReport {
    13	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
    14	    private final YearMonth month;
    15	    private final ReservationRepository reservationRepository;
    16	    private Map<RatePlan, ReportData> dataBySummary;
    17	
    18	    public RatePlansReport(YearMonth month, ReservationRepository reservationRepository) {
    19	        this.month = month;
    20	        this.reservationRepository = reservationRepository;
    21	    }
    22	
    23	    @Override
    24	    protected String reportName() {
    25	        return "rate-plans";
    26	    }
    27	
    28	    @Override
    29	    protected String period() {
    30	        return month.format(MONTH_FORMATTER);
    31	    }
    32	
    33	    @Override
    34	    protected String headerLine() {
    35	        return "rate_plan,reservations,amount";
    36	    }
    37	
    38	    @Override
    39	    protected List<String> dataLines() {
    40	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month).stream()
    41	                .filter(r -> r.getNetRevenue().compareTo(BigDecimal.ZERO) > 0)
    42	                .toList();
    43	
    44	        dataBySummary = new LinkedHashMap<>();
    45	        dataBySummary.put(RatePlan.STANDARD, new ReportData());
    46	        dataBySummary.put(RatePlan.NON_REFUNDABLE, new ReportData());
    47	
    48	        for (Reservation r : reservations) {
    49	            ReportData data = dataBySummary.get(r.getRatePlan());
    50	            data.count++;
    51	            data.amount = data.amount.add(r.getNetRevenue());
    52	        }
    53	
    54	        List<String> lines = new ArrayList<>();
    55	        for (Map.Entry<RatePlan, ReportData> entry : dataBySummary.entrySet()) {
    56	            lines.add(String.format("%s,%d,%s",
    57	                entry.getKey().name(),
    58	                entry.getValue().count,
    59	                formatAmount(entry.getValue().amount)
    60	            ));
    61	        }
    62	
    63	        return lines;
    64	    }
    65	
    66	    @Override
    67	    protected String totalLine() {
    68	        int totalCount = dataBySummary.values().stream()
    69	                .mapToInt(d -> d.count)
    70	                .sum();
    71	        BigDecimal totalAmount = dataBySummary.values().stream()
    72	                .map(d -> d.amount)
    73	                .reduce(BigDecimal.ZERO, BigDecimal::add)
    74	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
    75	        return String.format("total,%d,%s", totalCount, formatAmount(totalAmount));
    76	    }
    77	
    78	    private String formatAmount(BigDecimal amount) {
    79	        return amount.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
    80	    }
    81	
    82	    private static class ReportData {
    83	        int count = 0;
    84	        BigDecimal amount = BigDecimal.ZERO.setScale(2, java.math.RoundingMode.HALF_EVEN);
    85	    }
    86	}
