    12	public class TourismTaxReport extends CsvReport {
    13	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    14	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
    15	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    16	
    17	    private final YearMonth month;
    18	    private final ReservationRepository reservationRepository;
    19	    private List<Reservation> reservations;
    20	
    21	    public TourismTaxReport(YearMonth month, ReservationRepository reservationRepository) {
    22	        this.month = month;
    23	        this.reservationRepository = reservationRepository;
    24	    }
    25	
    26	    @Override
    27	    protected String reportName() {
    28	        return "tourism-tax";
    29	    }
    30	
    31	    @Override
    32	    protected String period() {
    33	        return month.format(MONTH_FORMATTER);
    34	    }
    35	
    36	    @Override
    37	    protected String headerLine() {
    38	        return "reservation,room,check_in,check_out,guests,nights,tax";
    39	    }
    40	
    41	    @Override
    42	    protected List<String> dataLines() {
    43	        reservations = reservationRepository.findPaidByCheckInMonth(month);
    44	
    45	        List<String> lines = new ArrayList<>();
    46	        for (Reservation r : reservations) {
    47	            BigDecimal tax = calculateTax(r);
    48	            lines.add(String.format("%d,%s,%s,%s,%d,%d,%s",
    49	                r.getId(),
    50	                r.getRoomNumber(),
    51	                r.getCheckIn().format(DATE_FORMATTER),
    52	                r.getCheckOut().format(DATE_FORMATTER),
    53	                r.getGuests(),
    54	                r.getNights(),
    55	                formatAmount(tax)
    56	            ));
    57	        }
    58	
    59	        return lines;
    60	    }
    61	
    62	    @Override
    63	    protected String totalLine() {
    64	        BigDecimal total = reservations.stream()
    65	                .map(this::calculateTax)
    66	                .reduce(BigDecimal.ZERO, BigDecimal::add)
    67	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
    68	        return "total," + formatAmount(total);
    69	    }
    70	
    71	    private BigDecimal calculateTax(Reservation reservation) {
    72	        return TAX_PER_GUEST_PER_NIGHT
    73	                .multiply(new BigDecimal(reservation.getGuests()))
    74	                .multiply(new BigDecimal(reservation.getNights()))
    75	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
    76	    }
    77	
    78	    private String formatAmount(BigDecimal amount) {
    79	        return amount.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
    80	    }
    81	}
