    11	    public static boolean isHighSeason(LocalDate date) {
    12	        Month month = date.getMonth();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == Month.DECEMBER && day >= 15) {
    16	            return true;
    17	        }
    18	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    19	            return true;
    20	        }
    21	        if (month == Month.JULY) {
    22	            return true;
    23	        }
    24	        return false;
    25	    }
    26	
    27	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    28	        if (isHighSeason(night)) {
    29	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    30	                    .setScale(2, RoundingMode.HALF_EVEN);
    31	        }
    32	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    33	    }
    34	}
