     8	public class Reservation {
     9	    private final long id;
    10	    private final String roomNumber;
    11	    private final String guestName;
    12	    private final String guestEmail;
    13	    private final String guestCpf;
    14	    private final LocalDate checkIn;
    15	    private final LocalDate checkOut;
    16	    private final int guests;
    17	    private final RatePlan ratePlan;
    18	    private final int nights;
    19	    private final BigDecimal subtotal;
    20	    private final BigDecimal discount;
    21	    private final BigDecimal total;
    22	
    23	    private ReservationStatus status;
    24	    private BigDecimal amountPaid;
    25	    private BigDecimal refund;
    26	
    27	    public Reservation(long id, String roomNumber, RoomType roomType, String guestName,
    28	                      String guestEmail, String guestCpf, LocalDate checkIn, LocalDate checkOut,
    29	                      int guests, RatePlan ratePlan) {
    30	        this.id = id;
    31	        this.roomNumber = roomNumber;
    32	        this.guestName = guestName;
    33	        this.guestEmail = guestEmail;
    34	        this.guestCpf = guestCpf;
    35	        this.checkIn = checkIn;
    36	        this.checkOut = checkOut;
    37	        this.guests = guests;
    38	        this.ratePlan = ratePlan;
    39	        this.status = ReservationStatus.PENDING;
    40	        this.amountPaid = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
    41	        this.refund = null;
    42	
    43	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    44	        this.subtotal = calculateSubtotal(roomType.getNightlyRate(), checkIn, checkOut);
    45	        this.discount = ratePlan.applyDiscount(subtotal);
    46	        this.total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	
    49	    private BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    50	        BigDecimal sum = BigDecimal.ZERO;
    51	        LocalDate night = checkIn;
    52	        while (night.isBefore(checkOut)) {
    53	            BigDecimal nightPrice = PriceCalculator.calculateNightPrice(baseRate, night);
    54	            sum = sum.add(nightPrice);
    55	            night = night.plusDays(1);
    56	        }
    57	        return sum.setScale(2, RoundingMode.HALF_EVEN);
    58	    }
    59	
    60	    public void confirm() {
    61	        if (status != ReservationStatus.PENDING) {
    62	            throw new IllegalStateException("Only pending reservations can be confirmed");
    63	        }
    64	        this.status = ReservationStatus.CONFIRMED;
    65	        this.amountPaid = total;
    66	    }
    67	
    68	    public void checkIn() {
    69	        if (status != ReservationStatus.CONFIRMED) {
    70	            throw new IllegalStateException("Only confirmed reservations can check in");
    71	        }
    72	        this.status = ReservationStatus.CHECKED_IN;
    73	    }
    74	
    75	    public void checkOut() {
    76	        if (status != ReservationStatus.CHECKED_IN) {
    77	            throw new IllegalStateException("Only checked-in reservations can check out");
    78	        }
    79	        this.status = ReservationStatus.CHECKED_OUT;
    80	    }
    81	
    82	    public void cancel() {
    83	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
    84	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
    85	        }
    86	        this.status = ReservationStatus.CANCELLED;
    87	        this.refund = ratePlan.calculateRefund(amountPaid);
    88	    }
    89	
