 63	import java.time.temporal.ChronoUnit;
 64	
 65	public class Reservation {
 66	    private final long id;
 67	    private final String roomNumber;
 68	    private final String guestName;
 69	    private final String guestEmail;
 70	    private final String guestCpf;
 71	    private final LocalDate checkIn;
 72	    private final LocalDate checkOut;
 73	    private final int guests;
 74	    private final RatePlan ratePlan;
 75	    private final int nights;
 76	    private final BigDecimal subtotal;
 77	    private final BigDecimal discount;
 78	    private final BigDecimal total;
 79	
 80	    private ReservationStatus status;
 81	    private BigDecimal amountPaid;
 82	    private BigDecimal refund;
 83	
 84	    public Reservation(long id, String roomNumber, RoomType roomType, String guestName,
 85	                      String guestEmail, String guestCpf, LocalDate checkIn, LocalDate checkOut,
 86	                      int guests, RatePlan ratePlan) {
 87	        this.id = id;
 88	        this.roomNumber = roomNumber;
 89	        this.guestName = guestName;
 90	        this.guestEmail = guestEmail;
 91	        this.guestCpf = guestCpf;
 92	        this.checkIn = checkIn;
 93	        this.checkOut = checkOut;
 94	        this.guests = guests;
 95	        this.ratePlan = ratePlan;
 96	        this.status = ReservationStatus.PENDING;
 97	        this.amountPaid = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 98	        this.refund = null;
 99	
100	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
101	        this.subtotal = calculateSubtotal(roomType.getNightlyRate(), checkIn, checkOut);
102	        this.discount = ratePlan.applyDiscount(subtotal);
103	        this.total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
104	    }
105	
106	    private BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
107	        BigDecimal sum = BigDecimal.ZERO;
108	        LocalDate night = checkIn;
109	        while (night.isBefore(checkOut)) {
110	            BigDecimal nightPrice = PriceCalculator.calculateNightPrice(baseRate, night);
111	            sum = sum.add(nightPrice);
112	            night = night.plusDays(1);
113	        }
114	        return sum.setScale(2, RoundingMode.HALF_EVEN);
115	    }
116	
117	    public void confirm() {
118	        if (status != ReservationStatus.PENDING) {
119	            throw new IllegalStateException("Only pending reservations can be confirmed");
120	        }
121	        this.status = ReservationStatus.CONFIRMED;
122	        this.amountPaid = total;
123	    }
124	
125	    public void checkIn() {
126	        if (status != ReservationStatus.CONFIRMED) {
127	            throw new IllegalStateException("Only confirmed reservations can check in");
128	        }
129	        this.status = ReservationStatus.CHECKED_IN;
130	    }
131	
132	    public void checkOut() {
133	        if (status != ReservationStatus.CHECKED_IN) {
134	            throw new IllegalStateException("Only checked-in reservations can check out");
135	        }
136	        this.status = ReservationStatus.CHECKED_OUT;
137	    }
138	
139	    public void cancel() {
140	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
141	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
142	        }
143	        this.status = ReservationStatus.CANCELLED;
144	        this.refund = ratePlan.calculateRefund(amountPaid);
145	    }
146	
147	    public boolean occupiesNight(LocalDate night) {
148	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
149	    }
