232	import java.math.RoundingMode;
233	import java.time.LocalDate;
234	import java.time.Month;
235	
236	public class PriceCalculator {
237	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
238	
239	    public static boolean isHighSeason(LocalDate date) {
240	        Month month = date.getMonth();
241	        int day = date.getDayOfMonth();
242	
243	        if (month == Month.DECEMBER && day >= 15) {
244	            return true;
245	        }
246	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
247	            return true;
248	        }
249	        if (month == Month.JULY) {
250	            return true;
251	        }
252	        return false;
253	    }
254	
255	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
256	        if (isHighSeason(night)) {
257	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
258	                    .setScale(2, RoundingMode.HALF_EVEN);
259	        }
260	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
261	    }
262	}

