package com.pousadamarealta.api.dto;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.pousadamarealta.domain.Reservation;
import com.pousadamarealta.domain.Room;

import java.math.BigDecimal;
import java.time.LocalDate;

public record ReceiptDto(
        @JsonProperty("title") String title,
        @JsonProperty("reservationId") long reservationId,
        @JsonProperty("guestName") String guestName,
        @JsonProperty("guestCpf") String guestCpf,
        @JsonProperty("roomNumber") String roomNumber,
        @JsonProperty("roomType") String roomType,
        @JsonProperty("checkIn") LocalDate checkIn,
        @JsonProperty("checkOut") LocalDate checkOut,
        @JsonProperty("nights") int nights,
        @JsonProperty("subtotal") BigDecimal subtotal,
        @JsonProperty("discount") BigDecimal discount,
        @JsonProperty("total") BigDecimal total
) {
    public static ReceiptDto from(Reservation reservation, Room room) {
        return new ReceiptDto(
                "Comprovante de reserva",
                reservation.getId(),
                reservation.getGuestName(),
                reservation.getGuestCpf(),
                reservation.getRoomNumber(),
                room.getType().name(),
                reservation.getCheckIn(),
                reservation.getCheckOut(),
                reservation.getNights(),
                reservation.getSubtotal(),
                reservation.getDiscount(),
                reservation.getTotal()
        );
    }
}
                roomRepository.findByNumber("101").get().getType(),
                "Test Guest",
                "test@example.com",
                "12345678900",
                LocalDate.of(2027, 3, 10),
                LocalDate.of(2027, 3, 13),
                2,
                RatePlan.STANDARD
        ));
        reservation.confirm();

        YearMonth month = YearMonth.of(2027, 3);
        TourismTaxReport report = new TourismTaxReport(month, reservationRepository);

        String csv = report.generate();

        assertTrue(csv.contains(",2,3,27.00\n"));
        assertTrue(csv.endsWith("total,27.00"));
    }
}
